import type { ReactNode } from 'react';
import { cn } from '../lib/utils';

interface FormGridProps {
  cols?: 2 | 3;
  gap?: 3 | 4;
  className?: string;
  children: ReactNode;
}

export function FormGrid({ cols = 2, gap = 4, className, children }: FormGridProps) {
  return (
    <div
      className={cn(
        'grid grid-cols-1',
        cols === 2 && 'sm:grid-cols-2',
        cols === 3 && 'sm:grid-cols-3',
        gap === 3 && 'gap-3',
        gap === 4 && 'gap-4',
        className,
      )}
    >
      {children}
    </div>
  );
}
