import type { ReactNode } from 'react';
import { cn } from '../lib/utils';

interface LineItemsTableProps {
  title?: string;
  headers: string[];
  colTemplate: string;
  footer?: ReactNode;
  children: ReactNode;
  /** Optional action rendered inline with the title (e.g. an "Add" button) */
  action?: ReactNode;
}

export function LineItemsTable({
  title,
  headers,
  colTemplate,
  footer,
  children,
  action,
}: LineItemsTableProps) {
  return (
    <div className="border rounded-md overflow-hidden">
      {(title || action) && (
        <div className="px-3 py-2 flex items-center justify-between bg-muted/40">
          {title && (
            <span className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">
              {title}
            </span>
          )}
          {action && <span>{action}</span>}
        </div>
      )}
      <div className="divide-y text-sm">
        <div className={cn('grid px-3 py-2 text-xs font-medium text-muted-foreground', colTemplate)}>
          {headers.map((h, i) => (
            <span key={i}>{h}</span>
          ))}
        </div>
        {children}
        {footer}
      </div>
    </div>
  );
}

interface LineItemsTableRowProps {
  colTemplate: string;
  children: ReactNode;
  className?: string;
}

export function LineItemsTableRow({ colTemplate, children, className }: LineItemsTableRowProps) {
  return (
    <div className={cn('grid px-3 py-2 text-xs', colTemplate, className)}>{children}</div>
  );
}
