import axios, { AxiosInstance } from 'axios';
import { toast } from 'react-toastify';
import { SessionManager } from './session';

export function createApiClient(
  baseURL: string,
  session: SessionManager,
): AxiosInstance {
  const api = axios.create({ baseURL });

  let isRefreshing = false;
  let refreshSubscribers: Array<(token: string) => void> = [];

  const subscribeToRefresh = (callback: (token: string) => void): void => {
    refreshSubscribers.push(callback);
  };

  const onRefreshed = (token: string): void => {
    refreshSubscribers.forEach((cb) => cb(token));
    refreshSubscribers = [];
  };

  api.interceptors.request.use(
    (config) => {
      const stored = session.readSession();
      if (stored?.accessToken) {
        config.headers.Authorization = `Bearer ${stored.accessToken}`;
      }
      return config;
    },
    (error) => Promise.reject(error),
  );

  api.interceptors.response.use(
    (response) => response,
    async (error) => {
      const originalRequest = error.config;

      if (error.response?.status === 401 && !originalRequest._retry) {
        if (isRefreshing) {
          return new Promise((resolve) => {
            subscribeToRefresh((token) => {
              originalRequest.headers.Authorization = `Bearer ${token}`;
              resolve(api(originalRequest));
            });
          });
        }

        originalRequest._retry = true;
        isRefreshing = true;

        try {
          const stored = session.readSession();
          if (!stored) throw new Error('No session found');

          const response = await axios.post(`${baseURL}/refresh-token`, {
            refresh_token: stored.refreshToken,
          });

          const { access_token } = response.data;
          const newSession = {
            ...stored,
            accessToken: access_token,
            accessTokenExpires: Date.now() + session.SESSION_DURATION_MS,
          };

          session.persistSession(newSession);
          api.defaults.headers.common.Authorization = `Bearer ${access_token}`;
          onRefreshed(access_token);
          isRefreshing = false;

          return api(originalRequest);
        } catch (refreshError) {
          isRefreshing = false;
          refreshSubscribers = [];
          session.clearSession();

          if (typeof window !== 'undefined' && window.location.pathname !== '/login') {
            toast.error('Sua sessão expirou. Por favor, faça login novamente.');
            window.location.href = '/login';
          }

          return Promise.reject(refreshError);
        }
      }

      return Promise.reject(error);
    },
  );

  return api;
}
