import type { ReactNode } from 'react';
import { cn } from '../lib/utils';

interface FormSectionProps {
  title: string;
  children: ReactNode;
  gap?: 3 | 4;
  className?: string;
}

export function FormSection({ title, children, gap = 4, className }: FormSectionProps) {
  return (
    <fieldset className={cn('flex flex-col', gap === 3 ? 'gap-3' : 'gap-4', className)}>
      <legend className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-1">
        {title}
      </legend>
      {children}
    </fieldset>
  );
}
