import React, { useEffect, useState } from 'react';
import { useController, Control, FieldValues, Path } from 'react-hook-form';
import { FormControl, FormItem, FormLabel, FormMessage } from '../ui/form';
import { Input } from '../ui/input';

const formatCurrency = (value: number) =>
  value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const unformatCurrency = (value: string | number) => {
  if (typeof value === 'number') {
    return value.toString().replace(/[^\d,-]/g, '').replace(',', '.');
  }
  if (typeof value === 'string') {
    return value.replace(/[^\d,-]/g, '').replace(',', '.');
  }
  return '';
};

interface MoneyInputProps<TFieldValues extends FieldValues> {
  control: Control<TFieldValues>;
  name: Path<TFieldValues>;
  label: string;
}

const MoneyInput = <TFieldValues extends FieldValues>({
  control,
  name,
  label,
}: MoneyInputProps<TFieldValues>) => {
  const {
    field,
    fieldState: { error },
  } = useController({
    name,
    control,
    rules: {
      validate: (value) =>
        parseFloat(value) > 0 || 'O valor deve ser maior que zero',
    },
  });

  const [displayValue, setDisplayValue] = useState('');
  const [isFocused, setIsFocused] = useState(false);

  useEffect(() => {
    if (!isFocused) {
      setDisplayValue(formatCurrency(parseFloat(field.value) || 0));
    }
  }, [field.value, isFocused]);

  const handleFocus = () => {
    setIsFocused(true);
    setDisplayValue(field.value);
  };

  const handleBlur = () => {
    setIsFocused(false);
    field.onChange(parseFloat(unformatCurrency(displayValue)));
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setDisplayValue(e.target.value);
  };

  return (
    <FormItem>
      <FormLabel>{label}</FormLabel>
      <FormControl>
        <Input
          type="text"
          {...field}
          onFocus={handleFocus}
          onBlur={handleBlur}
          onChange={handleChange}
          value={displayValue || ''}
        />
      </FormControl>
      {error && <FormMessage>{error.message}</FormMessage>}
    </FormItem>
  );
};

export default MoneyInput;
