import { UserSession } from '../types/auth';

export const SESSION_DURATION_MS = 60 * 60 * 1000;
export const REFRESH_THRESHOLD_MS = 5 * 60 * 1000;

export interface SessionManager {
  SESSION_KEY: string;
  SESSION_DURATION_MS: number;
  REFRESH_THRESHOLD_MS: number;
  persistSession: (session: UserSession) => void;
  clearSession: () => void;
  readSession: () => UserSession | null;
}

export function createSessionManager(sessionKey: string): SessionManager {
  function persistSession(session: UserSession): void {
    const serialized = JSON.stringify(session);
    localStorage.setItem(sessionKey, serialized);
    document.cookie = `${sessionKey}=${encodeURIComponent(serialized)}; path=/; max-age=${SESSION_DURATION_MS / 1000}; SameSite=Lax; Secure`;
  }

  function clearSession(): void {
    localStorage.removeItem(sessionKey);
    document.cookie = `${sessionKey}=; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT`;
  }

  function readSession(): UserSession | null {
    try {
      const raw = localStorage.getItem(sessionKey);
      if (!raw) return null;
      return JSON.parse(raw) as UserSession;
    } catch {
      return null;
    }
  }

  return {
    SESSION_KEY: sessionKey,
    SESSION_DURATION_MS,
    REFRESH_THRESHOLD_MS,
    persistSession,
    clearSession,
    readSession,
  };
}
